create table if not exists public."transaction"(transaction_id bigint generated always as identity primary key,tran_number text not null unique,tran_date date not null,transaction_type_id bigint not null references public.transaction_types(transaction_type_id),subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),currency_id bigint not null references public.currencies(currency_id),exchange_rate numeric(24,10) not null default 1 check(exchange_rate>0),fiscal_period_id bigint not null references public.fiscal_periods(fiscal_period_id),customer_id bigint references public.customers(customer_id),supplier_id bigint references public.suppliers(supplier_id),payment_term_id bigint references public.payment_terms(term_id),total_amount numeric(24,6) not null default 0,status_id bigint not null references public.status(status_id),check(not(customer_id is not null and supplier_id is not null)));
create table if not exists public.transaction_line(transaction_line_id bigint generated always as identity primary key,transaction_id bigint not null references public."transaction"(transaction_id) on delete cascade,line_number integer not null check(line_number>0),product_id bigint references public.products(product_id),account_id bigint references public.chart_accounts(account_id),quantity numeric(24,6) not null default 1,unit_price numeric(24,6) not null default 0,net_amount numeric(24,6) not null default 0,tax_amount numeric(24,6) not null default 0,gross_amount numeric(24,6) not null default 0,department_id bigint references public.departments(department_id),class_id bigint references public.classes(class_id),location_id bigint references public.locations(location_id),tax_code_id bigint references public.tax_codes(tax_code_id),unique(transaction_id,line_number));
alter table public."transaction" enable row level security;alter table public.transaction_line enable row level security;
do $$declare t text;begin foreach t in array array['transaction','transaction_line']loop execute format('drop policy if exists "transaction_engine_select" on public.%I',t);execute format('drop policy if exists "transaction_engine_insert" on public.%I',t);execute format('drop policy if exists "transaction_engine_update" on public.%I',t);execute format('drop policy if exists "transaction_engine_delete" on public.%I',t);execute format('create policy "transaction_engine_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "transaction_engine_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "transaction_engine_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "transaction_engine_delete" on public.%I for delete to authenticated using(true)',t);end loop;end$$;
